add_action( 'woocommerce_before_single_product', 'perfectpixel_product_video_setup' );

function perfectpixel_product_video_url( $product_id ) {
	foreach ( explode( '|', '{{product_videos}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && (int) $parts[0] === (int) $product_id ) {
			return esc_url_raw( $parts[1] );
		}
	}
	return '';
}

function perfectpixel_product_video_setup() {
	global $product;
	if ( $product && perfectpixel_product_video_url( $product->get_id() ) ) {
		remove_action( 'woocommerce_before_single_product_summary', 'woocommerce_show_product_images', 20 );
		add_action( 'woocommerce_before_single_product_summary', 'perfectpixel_product_video_output', 20 );
	}
}

function perfectpixel_product_video_output() {
	global $product;
	$embed = wp_oembed_get( perfectpixel_product_video_url( $product->get_id() ) );
	if ( $embed ) {
		echo '<div class="woocommerce-product-gallery images perfectpixel-product-video" style="opacity:1"><div style="position:relative;padding-top:56.25%">';
		echo str_replace( '<iframe ', '<iframe style="position:absolute;inset:0;width:100%;height:100%" ', $embed ); // oEmbed HTML from WordPress' trusted providers.
		echo '</div></div>';
	} else {
		woocommerce_show_product_images(); // Fall back to the images if the URL cannot be embedded.
	}
}
